// lib/storage/src/content_manager/collection_meta_ops.rs:114-126 (REST request schema)
    pub vectors: VectorsConfig,
    /// For auto sharding:
    /// Number of shards in collection.
    ///  - Default is 1 for standalone, otherwise equal to the number of nodes
    ///  - Minimum is 1
    ///
    /// For custom sharding:
    /// Number of shards in collection per shard group.
    ///  - Default is 1, meaning that each shard key will be mapped to a single shard
    ///  - Minimum is 1
    #[serde(default)]
    #[validate(range(min = 1))]
    pub shard_number: Option<u32>,

// lib/storage/src/content_manager/toc/create_collection.rs:132-137
        let collection_params = CollectionParams {
            vectors,
            sparse_vectors,
            shard_number: NonZeroU32::new(shard_number)
                .ok_or_else(|| StorageError::bad_input("`shard_number` cannot be 0"))?,

// lib/storage/src/content_manager/toc/mod.rs:485-489,512-513 (distribution proposal entry)
        let shard_number = op
            .create_collection
            .shard_number
            .and_then(NonZeroU32::new)
            .unwrap_or(suggested_shard_number);
        ...
        let shard_distribution =
            ShardDistributionProposal::new(shard_number, replication_factor, &known_peers);

// lib/storage/src/content_manager/shard_distribution.rs:90-99 (the fatal materialization)
        // Get fair distribution of shards on peers
        let distribution = (0..shard_number.get())
            .map(|shard_id| {
                let replicas =
                    repeat_with(|| min_heap.peek_mut().unwrap().0.get_and_inc_shard_count())
                        .take(replica_number)
                        .collect();
                (shard_id, replicas)
            })
            .collect();

